components.css:
.ds-btn-primary { background: #FACC15; color: #000; padding: 14px 32px; border-radius: 12px; font-size: 14px; font-weight: 900; text-transform: uppercase; letter-spacing: 0.05em; border: none; cursor: pointer; transition: background 200ms cubic-bezier(0.4,0,0.2,1), transform 200ms cubic-bezier(0.4,0,0.2,1), box-shadow 200ms cubic-bezier(0.4,0,0.2,1); box-shadow: 0 0 0 0 transparent; }
.ds-btn-primary:hover { background: #EAB308; transform: translateY(-2px); box-shadow: 0 0 25px -4px rgba(250,204,21,0.45); }
.ds-btn-primary:active { transform: translateY(0); }
.ds-btn-primary:focus-visible { outline: 2px solid #FACC15; outline-offset: 3px; }

.ds-btn-secondary { background: transparent; color: #0EA5E9; padding: 14px 32px; border-radius: 12px; font-size: 14px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; border: 1.5px solid rgba(14,165,233,0.5); cursor: pointer; transition: background 200ms cubic-bezier(0.4,0,0.2,1), border-color 200ms cubic-bezier(0.4,0,0.2,1); }
.ds-btn-secondary:hover { background: rgba(14,165,233,0.1); border-color: #0EA5E9; }
.ds-btn-secondary:focus-visible { outline: 2px solid #0EA5E9; outline-offset: 3px; }

.ds-card-product { background: #161F2E; border: 1px solid #1E293B; border-radius: 16px; overflow: hidden; transition: transform 200ms cubic-bezier(0.4,0,0.2,1), border-color 200ms cubic-bezier(0.4,0,0.2,1); }
.ds-card-product:hover { transform: translateY(-4px); border-color: rgba(250,204,21,0.3); }
.ds-card-image { aspect-ratio: 4/3; background: #111722; display: flex; align-items: center; justify-content: center; font-size: 2rem; }
.ds-card-title { padding: 16px 16px 4px; font-size: 1rem; font-weight: 800; color: #F1F5F9; }
.ds-card-price { padding: 4px 16px 16px; font-size: 0.875rem; font-weight: 700; color: #FACC15; font-family: monospace; }

.ds-navbar { position: sticky; top: 0; z-index: 50; background: rgba(10,15,23,0.95); backdrop-filter: blur(12px); border-bottom: 1px solid rgba(148,163,184,0.15); padding: 0 24px; height: 80px; display: flex; align-items: center; justify-content: space-between; }
.ds-logo { font-size: 1.5rem; font-weight: 900; color: #F1F5F9; }
.ds-nav-links { display: flex; gap: 32px; list-style: none; }
.ds-nav-links a { color: #94A3B8; font-size: 14px; font-weight: 600; text-decoration: none; transition: color 200ms; }
.ds-nav-links a:hover { color: #FACC15; }
.ds-cart-btn { background: none; border: none; font-size: 1.25rem; cursor: pointer; padding: 8px; border-radius: 8px; transition: background 200ms; }
.ds-cart-btn:hover { background: rgba(250,204,21,0.1); }

.ds-price { display: inline-flex; align-items: baseline; gap: 2px; font-family: monospace; }
.ds-currency { font-size: 0.875rem; font-weight: 700; color: #FACC15; }
.ds-amount { font-size: 1.25rem; font-weight: 900; color: #FACC15; }
